            .env("SIFR_CACHE_DIR", scope.join("cache"))
            .status()
            .expect("nested generated child");
        assert!(status.success(), "nested generated child failed: {status}");
        std::fs::remove_dir_all(scope).expect("test scope cleanup");
        return;
